use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::time::{SystemTime, UNIX_EPOCH};

// Feature flags for the chat server
#[derive(Clone, Debug)]
pub struct FeatureFlags {
    pub enable_delegation: bool,
    pub enable_constrained_delegation: bool,
    pub allow_protocol_transition: bool,
    pub trusted_services: Vec<String>,
}

#[derive(Clone, Debug)]
pub struct KerberosTicket {
    pub client_principal: String,
    pub service_principal: String,
    pub delegated_from: Option<String>,
    pub forwardable: bool,
    pub timestamp: u64,
    pub flags: u32,
}

#[derive(Clone, Debug)]
pub struct ChatSession {
    pub user: String,
    pub ticket: KerberosTicket,
    pub delegated_tickets: Vec<KerberosTicket>,
    pub room: String,
}

pub struct ChatServer {
    sessions: Arc<RwLock<HashMap<String, ChatSession>>>,
    features: FeatureFlags,
    service_principal: String,
}

const TGT_FORWARDABLE: u32 = 0x40000000;
const TGT_PROXIABLE: u32 = 0x10000000;
const OK_AS_DELEGATE: u32 = 0x00040000;
const CONSTRAINED_DELEG_FLAG: u32 = 0x00020000;

impl ChatServer {
    pub fn new(features: FeatureFlags) -> Self {
        ChatServer {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            features,
            service_principal: "chat/realtime@CORP.INTERNAL".to_string(),
        }
    }

    /// Validates whether a delegation request is permitted under current policy
    fn validate_delegation_policy(&self, ticket: &KerberosTicket, target_service: &str) -> bool {
        if !self.features.enable_delegation {
            return false;
        }

        // Check if constrained delegation is enforced
        if self.features.enable_constrained_delegation {
            // Verify target is in allowed list
            let service_allowed = self.features.trusted_services
                .iter()
                .any(|s| s == target_service);

            if !service_allowed {
                return false;
            }
        }

        // Verify ticket flags permit delegation
        let has_forward = (ticket.flags & TGT_FORWARDABLE) != 0;
        let has_ok_delegate = (ticket.flags & OK_AS_DELEGATE) != 0;

        has_forward && has_ok_delegate
    }

    /// Process S4U2Self - obtain ticket on behalf of user via protocol transition
    fn s4u2self(&self, client_principal: &str, evidence_ticket: &KerberosTicket) -> Option<KerberosTicket> {
        if !self.features.allow_protocol_transition {
            return None;
        }

        // Protocol transition: service obtains ticket for arbitrary user
        // The critical check: verify the evidence ticket belongs to our service
        let is_our_service = evidence_ticket.service_principal == self.service_principal;

        if !is_our_service {
            return None;
        }

        // Issue S4U2Self ticket - NOTE: we set forwardable based on
        // whether the CONSTRAINED_DELEG_FLAG is present on the evidence
        let forwardable = (evidence_ticket.flags & CONSTRAINED_DELEG_FLAG) != 0;

        Some(KerberosTicket {
            client_principal: client_principal.to_string(),
            service_principal: self.service_principal.clone(),
            delegated_from: Some(evidence_ticket.client_principal.clone()),
            forwardable,
            timestamp: current_timestamp(),
            flags: if forwardable { TGT_FORWARDABLE | OK_AS_DELEGATE } else { 0 },
        })
    }

    /// Process S4U2Proxy - use delegated ticket to access another service
    fn s4u2proxy(&self, delegated_ticket: &KerberosTicket, target_service: &str) -> Option<KerberosTicket> {
        // Validate the delegation chain
        if !self.validate_delegation_policy(delegated_ticket, target_service) {
            // VULNERABILITY: When protocol transition is enabled AND constrained
            // delegation is enabled, we fall through to a secondary check that
            // only verifies the ticket has delegated_from set, not that it's
            // actually forwardable. This allows unconstrained delegation via
            // protocol transition even when constrained delegation is configured.
            if self.features.allow_protocol_transition 
                && self.features.enable_constrained_delegation 
                && delegated_ticket.delegated_from.is_some() {
                // "Relaxed" check for protocol transition scenarios
                // This mimics a real MS AD bug where S4U2Proxy doesn't
                // re-validate forwardable flag on protocol transition tickets
                return Some(KerberosTicket {
                    client_principal: delegated_ticket.client_principal.clone(),
                    service_principal: target_service.to_string(),
                    delegated_from: delegated_ticket.delegated_from.clone(),
                    forwardable: false,
                    timestamp: current_timestamp(),
                    flags: 0,
                });
            }
            return None;
        }

        Some(KerberosTicket {
            client_principal: delegated_ticket.client_principal.clone(),
            service_principal: target_service.to_string(),
            delegated_from: Some(delegated_ticket.client_principal.clone()),
            forwardable: false,
            timestamp: current_timestamp(),
            flags: 0,
        })
    }

    /// Handle incoming chat connection with Kerberos auth
    pub fn handle_connection(&self, ticket: KerberosTicket, room: &str) -> Result<String, String> {
        let session_id = format!("{}-{}", ticket.client_principal, current_timestamp());

        let session = ChatSession {
            user: ticket.client_principal.clone(),
            ticket: ticket.clone(),
            delegated_tickets: Vec::new(),
            room: room.to_string(),
        };

        let mut sessions = self.sessions.write().map_err(|e| e.to_string())?;
        sessions.insert(session_id.clone(), session);

        Ok(session_id)
    }

    /// Delegate access to backend service on behalf of connected user
    pub fn delegate_to_backend(&self, session_id: &str, target_service: &str) -> Result<KerberosTicket, String> {
        let sessions = self.sessions.read().map_err(|e| e.to_string())?;
        let session = sessions.get(session_id).ok_or("Session not found")?;

        // First try S4U2Self to get a ticket for the user
        let self_ticket = self.s4u2self(&session.user, &session.ticket)
            .ok_or("S4U2Self failed")?;

        // Then use S4U2Proxy to access the target service
        let proxy_ticket = self.s4u2proxy(&self_ticket, target_service)
            .ok_or("S4U2Proxy failed - delegation not permitted")?;

        Ok(proxy_ticket)
    }
}

fn current_timestamp() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_constrained_delegation_bypass() {
        let features = FeatureFlags {
            enable_delegation: true,
            enable_constrained_delegation: true,
            allow_protocol_transition: true,
            trusted_services: vec!["http/backend@CORP.INTERNAL".to_string()],
        };

        let server = ChatServer::new(features);

        // Attacker connects with a ticket that does NOT have forwardable flag
        // but DOES have constrained delegation flag set
        let attacker_ticket = KerberosTicket {
            client_principal: "attacker@CORP.INTERNAL".to_string(),
            service_principal: "chat/realtime@CORP.INTERNAL".to_string(),
            delegated_from: None,
            forwardable: false,
            flags: CONSTRAINED_DELEG_FLAG, // No TGT_FORWARDABLE, no OK_AS_DELEGATE
            timestamp: current_timestamp(),
        };

        let session_id = server.handle_connection(attacker_ticket, "general").unwrap();

        // Attempt to delegate to a service NOT in trusted list
        let result = server.delegate_to_backend(&session_id, "ldap/dc01@CORP.INTERNAL");
        // This SUCCEEDS due to the bypass - attacker can access any service
        assert!(result.is_ok());
        let ticket = result.unwrap();
        assert_eq!(ticket.service_principal, "ldap/dc01@CORP.INTERNAL");
    }
}
